jQuery(document).ready(function ($) {
  const yearFilters = $('.year-filters input[type="radio"]');
  let page = 2;
  let loading = false;
  let lastScrollTop = 0;
  const articlesPerPage = 10;

  function loadMorePosts() {
    if (loading) return;
    loading = true;

    $.ajax({
      url: astra_params.ajaxurl,
      type: "POST",
      data: {
        action: "load_more_posts",
        page: page,
      },
      success: function (response) {
        if (response) {
          $("#main").append(response);
          page++;
          loading = false;
        }
      },
    });
  }

  function initializeInfiniteScroll() {
    $(window).on("scroll", function () {
      const scrollTop = $(window).scrollTop();
      if (
        scrollTop + $(window).height() >= $(document).height() - 100 &&
        !loading
      ) {
        loadMorePosts();
      } else if (scrollTop < lastScrollTop) {
        removeRecentPosts();
      }
      lastScrollTop = scrollTop <= 0 ? 0 : scrollTop;
    });
  }

  function removeRecentPosts() {
    const main = $("#main");
    const articles = main.find(".article-link-wrapper");
    if (articles.length > articlesPerPage) {
      const articlesToRemove = articles.length - articlesPerPage;
      for (
        let i = articles.length - 1;
        i >= articles.length - articlesToRemove;
        i--
      ) {
        articles.eq(i).remove();
      }
    }
  }

  yearFilters.on("change", function () {
    const checkedFilter = $('.year-filters input[type="radio"]:checked');

    if (!checkedFilter.length || checkedFilter.val() === "") {
      if ($("body").hasClass("page-template-blog_archive")) {
        page = 2;
        loading = false;
        $("#main").empty(); // Vider les articles existants
        $("#debug-filter-year").text("Filter Year: All"); // Afficher la valeur de filter_year dans la page
        loadMorePosts(); // Charger les premiers articles
        initializeInfiniteScroll();
      }
    } else {
      $(window).off("scroll");
      $("#main").empty(); // Vider les articles existants
      const filterYear = checkedFilter.val();
      $("#debug-filter-year").text("Filter Year: " + filterYear); // Afficher la valeur de filter_year dans la page
      loadFilteredPosts(filterYear);
    }
  });

  function loadFilteredPosts(filterYear) {
    $("#debug-filter-year").text("Filter Year: " + filterYear); // Afficher la valeur de filter_year dans la page
    $.ajax({
      url: astra_params.ajaxurl,
      type: "GET",
      data: {
        action: "load_filtered_posts",
        filter_year: filterYear,
      },
      success: function (response) {
        $("#debug-ajax-response").text("AJAX Response: " + response); // Afficher la réponse AJAX dans la page
        if (response) {
          $("#main").html(response);
        }
      },
      error: function (xhr, status, error) {
        console.error("Erreur lors de la requête AJAX:", status, error);
      },
    });
  }

  // Initialiser l'infinite scroll si aucun filtre n'est sélectionné au chargement de la page
  if ($("body").hasClass("page-template-blog_archive")) {
    initializeInfiniteScroll();
  }

  // Ajouter la classe 'selected' au label parent de l'input sélectionné par défaut
  const defaultSelected = $('.year-filters input[type="radio"]:checked');
  if (defaultSelected.length) {
    defaultSelected.parent().addClass("selected");
  }
});
